 c.selections=[{id:'proof-artificer',entry:structuredClone(owner),level,quantity:1,equipped:false},...(pact?[{id:'proof-warlock',entry:structuredClone(warlock),level:pact,quantity:1,equipped:false}]:[]),...[[sword,'weapon-a'],[sword,'weapon-b'],[signet,'ring-a'],[signet,'ring-b'],[robes,'robes-a']].map(([entry,id])=>({id,entry:structuredClone(entry),level:1,quantity:1,equipped:false,attuned:false}))];
